package com.bank.order.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import org.springframework.data.domain.AbstractAggregateRoot;
import com.bank.order.event.OrderPlacedEvent;
import com.bank.order.event.OrderShippedEvent;

@Entity
@Table(name = "orders")
public class Order extends AbstractAggregateRoot<Order> {
    @Id private String orderId;
    private String accountId;
    private BigDecimal amount;
    @Enumerated(EnumType.STRING) private Status status = Status.NEW;

    protected Order() { }  // JPA

    public Order(String orderId, String accountId, BigDecimal amount) {
            this.orderId = orderId;
            this.accountId = accountId
            this.amount = amount;
    }

    // State transition + domain event. registerEvent is published on save().
    public void place() {
        if (status != Status.NEW)
            throw new IllegalStateException("Order " + orderId + " already placed");
        this.status = Status.PLACED;
        registerEvent(new OrderPlacedEvent(orderId, accountId, amount));
    }

    public void ship() {
        if (status != Status.PLACED)
            throw new IllegalStateException("Order " + orderId + " not in PLACED state");
        this.status = Status.SHIPPED;
        registerEvent(new OrderShippedEvent(orderId));
    }

    public String getOrderId() { return orderId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public Status getStatus() { return status; }

    public enum Status { NEW, PLACED, SHIPPED }
}
