package com.bank.order.command;

import com.bank.order.domain.Order;
import com.bank.order.repository.OrderRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class OrderCommandHandler {
    private final OrderRepository repo;

    @Transactional
    public void handle(PlaceOrderCommand cmd) {
        Order o = new Order(cmd.orderId(), cmd.accountId(), cmd.amount());
        o.place();               // enforces transition + registers event
        repo.save(o);            // save() publishes the registered domain events
    }

    @Transactional
    public void handle(ShipOrderCommand cmd) {
        Order o = repo.findById(cmd.orderId())
                .orElseThrow(() -> new IllegalArgumentException("No order " + cmd.orderId()));
        o.ship();
        repo.save(o);
    }
}
