package com.bank.order.projection;

import com.bank.order.event.OrderPlacedEvent;
import com.bank.order.event.OrderShippedEvent;
import com.bank.order.readmodel.OrderSummaryView;
import com.bank.order.repository.OrderSummaryRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.event.TransactionalEventListener;
import org.springframework.transaction.event.TransactionPhase;
import java.time.LocalDateTime;

@Component
@Slf4j
@RequiredArgsConstructor
public class OrderProjection {
    private final OrderSummaryRepository summaryRepo;

    // Runs ONLY after the write transaction commits, in its own transaction.
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void onPlaced(OrderPlacedEvent e) {
        String holder = lookupHolder(e.accountId()); // pre-join the holder name
        summaryRepo.save(new OrderSummaryView(e.orderId(), e.accountId(),
                holder, e.amount(), "PLACED", LocalDateTime.now()));
        log.info("Projection: order {} PLACED for {}", e.orderId(), holder);
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void onShipped(OrderShippedEvent e) {
        summaryRepo.findById(e.orderId()).ifPresent(v -> {
            v.markShipped(LocalDateTime.now());
            summaryRepo.save(v);
            log.info("Projection: order {} SHIPPED", e.orderId());
        });
    }

    private String lookupHolder(String accountId) {
        return accountId.equals("SAV2001") ? "Rajesh Kumar" : "Priya Sharma";
    }
}
