package com.bank.order.web;
import com.bank.order.command.*;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1/commands/orders")
@RequiredArgsConstructor
class OrderCommandController {
    private final OrderCommandHandler handler;

    @PostMapping
    ResponseEntity<Void> place(@RequestBody PlaceOrderCommand cmd) {
        handler.handle(cmd);
        return ResponseEntity.status(HttpStatus.ACCEPTED).build();
    }
    @PostMapping("/{id}/ship")
    ResponseEntity<Void> ship(@PathVariable String id) {
        handler.handle(new ShipOrderCommand(id));
        return ResponseEntity.accepted().build();
    }
}
